using System;using System.Linq;using UnityEngine;using UnityEditor;
public static class ValidateExplorationDrive {
 public static object Main(){
 if(!Application.isPlaying)throw new Exception("Requires Play Mode");var world=UnityEngine.Object.FindAnyObjectByType<ExplorationWorld>();var player=world.vehicle;var source=player.GetComponent<VehiclePhysics>();var original=source.GetComponent<Rigidbody>();bool kinematic=original.isKinematic,paused=EditorApplication.isPaused;var velocity=original.linearVelocity;var angular=original.angularVelocity;var mode=Physics.simulationMode;RainSoakedRoad[] roads=Array.Empty<RainSoakedRoad>();float[] saved=Array.Empty<float>();GameObject clone=null,observer=null;
 try{EditorApplication.isPaused=true;Physics.simulationMode=SimulationMode.Script;original.isKinematic=true;
 Vector2 crossing=default,direction=default;bool found=false;foreach(var road in world.Map.Roads.Where(r=>r.adventure==0||r.adventure==2)){for(int i=1;i<road.points.Length&&!found;i++){var a=road.points[i-1];var b=road.points[i];int n=Mathf.CeilToInt(Vector2.Distance(a,b));for(int j=1;j<=n;j++){var p=Vector2.Lerp(a,b,j/(float)n);var previous=Vector2.Lerp(a,b,(j-1)/(float)n);if(p.magnitude<35||p.magnitude>190)continue;if(world.TileAt(new Vector3(p.x,0,p.y))!=world.TileAt(new Vector3(previous.x,0,previous.y))){crossing=p;direction=(b-a).normalized;found=true;break;}}}if(found)break;}if(!found)throw new Exception("No road seam");
 var start=crossing-direction*8;observer=new GameObject("Drive test streaming observer");observer.transform.position=new Vector3(start.x,0,start.y);world.vehicle=observer.transform;world.EnsureWindow(true);for(int i=0;i<25;i++)world.EnsureWindow(false);roads=world.GetComponentsInChildren<RainSoakedRoad>();saved=roads.Select(r=>r.Saturation).ToArray();foreach(var road in roads)road.RestoreSaturation(0);
 var forward=new Vector3(direction.x,0,direction.y);clone=UnityEngine.Object.Instantiate(source.gameObject,new Vector3(start.x,world.Map.Height(start)+.8f,start.y),Quaternion.LookRotation(forward));var car=clone.GetComponent<VehiclePhysics>();car.automaticSimulation=false;car.externalControl=true;clone.GetComponent<VehiclePlayerInput>().enabled=false;var sound=clone.GetComponent<VehicleAudio>();if(sound!=null)sound.enabled=false;var body=clone.GetComponent<Rigidbody>();body.isKinematic=false;car.Initialize();car.SetNeutral(false);car.SetFourWheelDrive(true);car.SetTransmission(false,true);Physics.SyncTransforms();Action step=()=>{car.Simulate(.01f);Physics.Simulate(.01f);SoftGroundRuts.AdvanceAll(.01f);};car.SetInput(new VehicleControlInput{brake=1});for(int i=0;i<150;i++)step();int before=car.Wheels.Count(w=>w.isGrounded);var from=body.position;car.SetInput(new VehicleControlInput{throttle=.8f});float peak=0,error=0;for(int i=0;i<600;i++){step();peak=Mathf.Max(peak,car.SpeedKmh);error=Mathf.Max(error,car.MaximumSoilContactErrorMetres);}car.SetInput(new VehicleControlInput{brake=1});for(int i=0;i<200;i++)step();float travel=Vector3.Dot(body.position-from,forward);float past=Vector3.Dot(body.position-new Vector3(crossing.x,0,crossing.y),forward);int after=car.Wheels.Count(w=>w.isGrounded);
 if(travel<10||past<1||after!=car.Wheels.Length||before!=car.Wheels.Length||error>.02f)throw new Exception("Drive failed travel="+travel+" grounded="+after+" error="+error);return new{success=true,travelled=travel,pastSeam=past,peakKmh=peak,groundedBefore=before,groundedAfter=after,maximumSoilContactError=error};
 }finally{if(clone!=null)UnityEngine.Object.DestroyImmediate(clone);for(int i=0;i<roads.Length;i++)if(roads[i]!=null)roads[i].RestoreSaturation(saved[i]);world.vehicle=player;world.EnsureWindow(true);Physics.SyncTransforms();original.isKinematic=kinematic;if(!kinematic){original.linearVelocity=velocity;original.angularVelocity=angular;}Physics.simulationMode=mode;EditorApplication.isPaused=paused;if(observer!=null)UnityEngine.Object.DestroyImmediate(observer);}
 }
}
